            pdf_links = [link for link in file_links if link['href'].endswith('.pdf')]

            if pdf_links:
                print('Found PDF links:')
                for link in pdf_links[:5]:
                    print(f'   {link.get_text(strip=True)} - https://commons.wikimedia.org{link[\"href\"]}')
            else:
                print('No PDF links found in search results')
        else:
            print('No specific references to 1959 standards found')
    else:
        print('No search form found')

